DROP TEMPORARY TABLE IF EXISTS `mythic_items`;
CREATE TEMPORARY TABLE `mythic_items` AS SELECT m.`new_entry`, m.`tier`, m.`new_name`, m.`new_display`, m.`price`, t.* FROM `mythic_map` m JOIN `item_template` t ON t.`entry` = m.`src_entry`;
UPDATE `mythic_items` SET `entry` = `new_entry`, `patch` = 0, `name` = `new_name`, `display_id` = COALESCE(`new_display`, `display_id`),
    `description` = CONCAT('Tier ', `tier`), `quality` = 4, `flags` = 0, `buy_count` = 1, `buy_price` = `price`, `sell_price` = ROUND(`price` / 10),
    `item_level` = 60 + `tier`, `required_level` = 0, `max_count` = 0, `bonding` = 1, `random_property` = 0, `set_id` = 0, `disenchant_id` = 0;
ALTER TABLE `mythic_items` DROP COLUMN `new_entry`, DROP COLUMN `tier`, DROP COLUMN `new_name`, DROP COLUMN `new_display`, DROP COLUMN `price`;
INSERT INTO `item_template` SELECT * FROM `mythic_items`;

INSERT INTO `bonk_item_stat` (`entry`, `power`, `max_health`, `armor`, `dodge`, `crit`, `crit_damage`, `shield`, `haste`, `area`, `pickup_range`, `luck`, `set_id`, `unlock_tier`)
SELECT `new_entry`, `power`, `max_health`, `armor`, `dodge`, `crit`, `crit_damage`, `shield`, `haste`, `area`, `pickup_range`, `luck`, 0, 3 FROM `mythic_map`;

DELETE v FROM `npc_vendor` v JOIN `bonk_item_stat` s ON s.`entry` = v.`item` WHERE v.`entry` = 900004 AND s.`unlock_tier` = 3;

DROP TEMPORARY TABLE IF EXISTS `mythic_map`;
DROP TEMPORARY TABLE IF EXISTS `mythic_items`;

END IF;
